#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a context manager structure
typedef struct {
    FILE *fp;
    char *mode; // "r" for reading, "w" for writing
} TAR_Context;

// Define the methods for the context manager
void tar_open(TAR_Context *ctx, const char *filename) {
    ctx->fp = fopen(filename, ctx->mode);
    if (!ctx->fp) {
        perror("Error opening file");
        exit(1);
    }
}

void tar_close(TAR_Context *ctx) {
    fclose(ctx->fp);
}

// Define a function to read from the tar archive
void tar_read(TAR_Context *ctx) {
    // Create a TAR struct to represent the tar archive
    TAR *tar = tar_open(ctx->fp, "r");
    if (!tar) {
        perror("Error opening tar archive");
        exit(1);
    }

    // Read the contents of the tar archive
    while (1) {
        char buf[512];
        int nbytes = fread(buf, 1, 512, ctx->fp);
        if (nbytes == 0) break;
        fwrite(buf, 1, nbytes, stdout);
    }

    // Close the tar archive
    tar_close(tar);
}

// Define a function to write to the tar archive
void tar_write(TAR_Context *ctx, const char *filename) {
    // Create a TAR struct to represent the tar archive
    TAR *tar = tar_open(ctx->fp, "w");
    if (!tar) {
        perror("Error opening tar archive");
        exit(1);
    }

    // Add the file to the tar archive
    thANDLE th = thOpen(tar, filename, "w");
    if (!th) {
        perror("Error adding file to tar archive");
        exit(1);
    }
    fwrite(filename, 1, strlen(filename), th);
    thClose(th);

    // Close the tar archive
    tar_close(tar);
}

int main() {
    TAR_Context ctx;
    ctx.mode = "r";

    // Open the tar archive using the with statement
    with (ctx) {
        tar_open(&ctx, "example.tar");
        tar_read(&ctx);
    }

    // Create a new tar archive and add a file to it
    ctx.mode = "w";
    with (ctx) {
        tar_write(&ctx, "file.txt");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h> // added for close, read, and write declarations

typedef struct {
    int fp; // initialized to -1
    char *mode; // "r" for reading, "w" for writing
} TAR_Context;

void tar_open(TAR_Context *ctx, const char *filename) {
    if (strcmp(ctx->mode, "r") == 0) {
        ctx->fp = open(filename, O_RDONLY);
    } else if (strcmp(ctx->mode, "w") == 0) {
        umask(S_IRUSR | S_IWUSR); // Set permission mask to restrict access
        ctx->fp = open(filename, O_CREAT | O_WRONLY, S_IRUSR | S_IWUSR);
    }
    if (ctx->fp < 0) {
        perror("Error opening file");
        exit(1);
    }
}

void tar_close(TAR_Context *ctx) {
    if (ctx->fp != -1) { // check if fp is valid before using it
        close(ctx->fp);
        ctx->fp = -1; // reset to -1 after closing
    }
}

void tar_read(TAR_Context *ctx) {
    if (ctx->fp != -1) { // check if fp is valid before using it
        char buf[512];
        int nbytes = read(ctx->fp, buf, 512);
        while (nbytes > 0) {
            fwrite(buf, 1, nbytes, stdout);
            nbytes = read(ctx->fp, buf, 512);
        }
    }
}

void tar_write(TAR_Context *ctx, const char *filename) {
    if (ctx->fp != -1) { // check if fp is valid before using it
        int fd = open("example.tar", O_CREAT | O_WRONLY, S_IRUSR | S_IWUSR);
        if (fd < 0) {
            perror("Error opening tar archive");
            exit(1);
        }

        // Add the file to the tar archive
        write(fd, filename, strlen(filename));
        close(fd);
    }
}

int main() {
    TAR_Context ctx;
    ctx.fp = -1; // initialize fp to -1
    ctx.mode = "r";

    tar_open(&ctx, "example.tar");
    tar_read(&ctx);
    tar_close(&ctx);

    // Create a new tar archive and add a file to it
    ctx.mode = "w";
    tar_write(&ctx, "file.txt");

    return 0;
}

